                          <MoreHorizontal />
                        </Button>
                      </DropdownMenuTrigger>
                      <DropdownMenuContent align="end">
                        <DropdownMenuItem
                          disabled={isMe}
                          onSelect={() =>
                            roleAction.run(() =>
                              setRole({
                                data: { userId: u.id, role: newRole },
                              }),
