export const Route = createFileRoute('/_app/')({
  loader: () => listBooks(),
  component: Library,
})

function Library() {
  const books = Route.useLoaderData()
  const { user } = Route.useRouteContext()
  const [query, setQuery] = useState('')

  const q = query.trim().toLowerCase()
  const shown = q
    ? books.filter((b) =>
        [b.title, ...b.authors].some((s) => s.toLowerCase().includes(q)),
      )
    : books

  return (
    <main className="mx-auto max-w-6xl px-4 py-8">
      <div className="flex flex-wrap items-center gap-3">
        <h1 className="mr-auto text-2xl font-semibold">Library</h1>
        {books.length > 0 && (
          <Input
            type="search"
            placeholder="Search"
            aria-label="Search title or author"
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            className="w-full sm:w-56"
          />
        )}
        {user.role === 'admin' && <AdminActions />}
      </div>
      {shown.length === 0 ? (
        <div className="mt-6 flex min-h-72 flex-col items-center justify-center gap-3 rounded-lg border border-dashed text-muted-foreground">
          <BookOpen className="size-8" />
          <p className="text-sm">
            {books.length ? 'No matches' : 'No books yet'}
          </p>
        </div>
      ) : (
        <ul className="mt-6 grid grid-cols-2 gap-x-4 gap-y-6 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-6">
          {shown.map((book) => (
            <li
              key={book.id}
              className={cn(book.missing && 'opacity-50 grayscale')}
            >
              <Link
                to="/books/$bookId"
                params={{ bookId: book.id }}
                className="group block"
              >
                <BookCover
                  {...book}
                  className="transition-shadow group-hover:shadow-md"
                />
                <p className="mt-2 line-clamp-2 text-sm font-medium">
                  {book.title}
                </p>
                <p className="line-clamp-1 text-xs text-muted-foreground">
                  {book.authors.join(', ')}
                </p>
              </Link>
            </li>
          ))}
        </ul>
      )}
    </main>
  )
}

function AdminActions() {
  const router = useRouter()
  const fileInput = useRef<HTMLInputElement>(null)
  const [busy, setBusy] = useState<'scan' | 'upload' | null>(null)
  const [error, setError] = useState('')

  async function run(kind: 'scan' | 'upload', action: () => Promise<void>) {
    setBusy(kind)
    setError('')
    try {
      await action()
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Request failed')
    } finally {
      setBusy(null)
      await router.invalidate()
    }
  }

  const scan = () =>
    run('scan', async () => {
      const result = await scanLibraryNow()
      if (result.error) throw new Error(result.error)
    })

  const upload = (files: File[]) =>
    run('upload', async () => {
      const failed: string[] = []
      for (const file of files) {
        const res = await fetch(
          `/api/books/upload?name=${encodeURIComponent(file.name)}`,
          { method: 'POST', body: file },
        )
        if (!res.ok) failed.push(await res.text())
      }
      if (failed.length) throw new Error(failed.join('. '))
    })

  return (
    <>
      <Button variant="outline" onClick={scan} disabled={busy !== null}>
        <RefreshCw className={cn(busy === 'scan' && 'animate-spin')} />
        Scan library
      </Button>
      <Button
        onClick={() => fileInput.current?.click()}
        disabled={busy !== null}
      >
        <Upload className={cn(busy === 'upload' && 'animate-pulse')} />
        Upload
      </Button>
      <input
        ref={fileInput}
        type="file"
        accept=".epub,application/epub+zip"
        multiple
        hidden
        onChange={(e) => {
          const files = [...(e.target.files ?? [])]
          e.target.value = ''
          if (files.length) void upload(files)
        }}
      />
      {error && <p className="w-full text-sm text-destructive">{error}</p>}
    </>
  )
}
import { cn } from '#/lib/utils'

type Props = {
  title: string
  authors: string[]
  coverUrl: string | null
  className?: string
}

// A stable hue per title, so a placeholder keeps its color between visits.
function hue(text: string) {
  let h = 0
  for (const char of text) h = (h * 31 + char.charCodeAt(0)) % 360
  return h
}

// The cover image, or a tinted block with the title for books without one.
export function BookCover({ title, authors, coverUrl, className }: Props) {
  const base = cn(
    'aspect-[2/3] w-full overflow-hidden rounded-md shadow-sm ring-1 ring-black/5',
    className,
  )
  if (coverUrl) {
    return (
      <img
        src={coverUrl}
        alt={title}
        loading="lazy"
        className={cn(base, 'bg-muted object-cover')}
      />
    )
  }
  const h = hue(title)
  return (
    <div
      className={cn(
        base,
        '@container flex flex-col justify-between p-3 text-left',
      )}
      style={{
        backgroundColor: `oklch(0.9 0.05 ${h})`,
        color: `oklch(0.32 0.07 ${h})`,
      }}
    >
      <span className="line-clamp-5 text-sm leading-snug font-semibold text-balance @[12rem]:text-xl">
        {title}
      </span>
      {authors[0] && (
        <span className="line-clamp-2 text-xs opacity-80 @[12rem]:text-sm">
          {authors[0]}
        </span>
      )}
    </div>
  )
}
#!/usr/bin/env bash
# Prepares a fresh Amp orb: Node dependencies, the Entire CLI, and the
# entire-agent-amp external agent. Idempotent; a warm run skips installed tools.
set -euo pipefail
cd "$(dirname "$0")/.."

GO_VERSION=1.26.10
ENTIRE_VERSION=0.12.2
# entireio/external-agents has no releases; pin the commit to build from.
ENTIRE_AGENT_AMP_REV=23c64f2861ddbfd2670cffafeb45f86bad6ebc2b

bin_dir="$HOME/.local/bin" # already on PATH in orb login shells
go_root="$HOME/.local/go"
case "$(uname -m)" in
  x86_64 | amd64) arch=amd64 ;;
  aarch64 | arm64) arch=arm64 ;;
  *) echo "unsupported arch: $(uname -m)" >&2; exit 1 ;;
esac
mkdir -p "$bin_dir"

step() {
  local name=$1 start=$SECONDS
  shift
  echo "==> $name"
  "$@"
  echo "    $name took $((SECONDS - start))s"
}

install_entire() {
  if "$bin_dir/entire" version 2>/dev/null | grep -Fq "Entire CLI $ENTIRE_VERSION"; then
    echo "    entire $ENTIRE_VERSION already installed"
    return
  fi
  local tmp
  tmp=$(mktemp -d)
  curl -fsSL "https://github.com/entireio/cli/releases/download/v$ENTIRE_VERSION/entire_linux_$arch.tar.gz" |
    tar xz -C "$tmp" entire git-remote-entire
  install -m 755 "$tmp/entire" "$tmp/git-remote-entire" "$bin_dir/"
  rm -rf "$tmp"
}

install_go() {
  if "$go_root/bin/go" version 2>/dev/null | grep -Fq "go$GO_VERSION "; then
    echo "    go $GO_VERSION already installed"
    return
  fi
  rm -rf "$go_root"
  curl -fsSL "https://go.dev/dl/go$GO_VERSION.linux-$arch.tar.gz" | tar xz -C "$(dirname "$go_root")"
}

install_entire_agent_amp() {
  # The pseudo-version embedded in the binary ends with the first 12 chars of the commit.
  if "$go_root/bin/go" version -m "$bin_dir/entire-agent-amp" 2>/dev/null | grep -Fq "${ENTIRE_AGENT_AMP_REV:0:12}"; then
    echo "    entire-agent-amp ${ENTIRE_AGENT_AMP_REV:0:12} already installed"
    return
  fi
  GOBIN="$bin_dir" "$go_root/bin/go" install \
    "github.com/entireio/external-agents/agents/entire-agent-amp/cmd/entire-agent-amp@$ENTIRE_AGENT_AMP_REV"
}

step "pnpm install" pnpm install --frozen-lockfile
step "entire CLI" install_entire
step "go toolchain" install_go
step "entire-agent-amp" install_entire_agent_amp
