import type { ReadableStream as WebReadableStream } from 'node:stream/web'
import { createServerFn } from '@tanstack/react-start'
import { asc, eq } from 'drizzle-orm'

import { db } from '#/db'
import { opdsServers } from '#/db/schema'
import { HttpError, request } from '#/lib/metadata/http'
import { readFeed, searchFeed } from '#/lib/opds'
import { UploadError, uploadBook } from '#/lib/scanner'
import { requireAdmin } from '#/lib/user-functions'

// The Market (admin only): OPDS servers, browsing them, and adding their books
// to the library through the same import path as uploads.

const DOWNLOAD_TIMEOUT_MS = 5 * 60_000

const str = (value: unknown, max = 2000) =>
  typeof value === 'string' ? value.trim().slice(0, max) : ''

function checkUrl(value: unknown) {
  const url = str(value)
  if (!/^https?:\/\/\S+$/i.test(url)) throw new Error('Enter an http(s) URL')
  return url
}

const message = (err: unknown) =>
  err instanceof Error ? err.message : 'Request failed'

export const listOpdsServers = createServerFn({ method: 'GET' }).handler(
  async () => {
    await requireAdmin()
    return db
      .select({
        id: opdsServers.id,
        name: opdsServers.name,
        url: opdsServers.url,
      })
      .from(opdsServers)
      .orderBy(asc(opdsServers.id))
      .all()
  },
)

// Reads the feed first, so a typo is caught here and the name can default to
// the catalog's own title.
export const addOpdsServer = createServerFn({ method: 'POST' })
  .validator((data: { name: string; url: string }) => ({
    name: str(data.name, 100),
    url: checkUrl(data.url),
  }))
  .handler(async ({ data }) => {
    await requireAdmin()
    let feed
    try {
      feed = await readFeed(data.url)
    } catch (err) {
      throw new Error(`Could not read the catalog: ${message(err)}`)
    }
    db.insert(opdsServers)
      .values({ name: data.name || feed.title, url: data.url })
      .run()
  })

export const removeOpdsServer = createServerFn({ method: 'POST' })
  .validator((id: number) => Number(id))
  .handler(async ({ data: id }) => {
    await requireAdmin()
    db.delete(opdsServers).where(eq(opdsServers.id, id)).run()
  })

// Loads a feed of a server (its root unless `url` is given), or search results
// from that feed's search. Errors come back as data so the page can show them.
export const browseOpds = createServerFn({ method: 'GET' })
  .validator((data: { serverId: number; url?: string; q?: string }) => ({
    serverId: Number(data.serverId),
    url: data.url ? checkUrl(data.url) : undefined,
    q: str(data.q, 200),
  }))
  .handler(async ({ data }) => {
    await requireAdmin()
    const server = db
      .select()
      .from(opdsServers)
      .where(eq(opdsServers.id, data.serverId))
      .get()
    if (!server) return { error: 'Unknown server' }
    const url = data.url ?? server.url
    try {
      const feed = data.q ? await searchFeed(url, data.q) : await readFeed(url)
      return { feed }
    } catch (err) {
      return { error: message(err) }
    }
  })

// Downloads an EPUB from a catalog into the library.
export const addFromOpds = createServerFn({ method: 'POST' })
  .validator((data: { href: string; title: string }) => ({
    href: checkUrl(data.href),
    title: str(data.title, 200) || 'book',
  }))
  .handler(async ({ data }) => {
    await requireAdmin()
    const res = await request(data.href, DOWNLOAD_TIMEOUT_MS)
    if (!res.ok || !res.body) throw new HttpError(res.status)
    try {
      return await uploadBook(
        `${data.title}.epub`,
        res.body as WebReadableStream<Uint8Array>,
      )
    } catch (err) {
      if (err instanceof UploadError) {
        throw new Error('The download is not a valid EPUB')
      }
      throw err
    }
  })

import { useState } from 'react'
import { createFileRoute, useRouter } from '@tanstack/react-router'
import { Trash2 } from 'lucide-react'

import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from '#/components/ui/alert-dialog'
import { Button } from '#/components/ui/button'
import {
  Dialog,
  DialogContent,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '#/components/ui/dialog'
import { Input } from '#/components/ui/input'
import { Label } from '#/components/ui/label'
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '#/components/ui/table'
import {
  addOpdsServer,
  listOpdsServers,
  removeOpdsServer,
} from '#/lib/opds-functions'

export const Route = createFileRoute('/_app/settings/opds')({
  loader: () => listOpdsServers(),
  component: OpdsServers,
})

type Server = Awaited<ReturnType<typeof listOpdsServers>>[number]

function useAction() {
  const router = useRouter()
  const [error, setError] = useState('')
  const [pending, setPending] = useState(false)

  async function run(action: () => Promise<unknown>) {
    setPending(true)
    setError('')
    try {
      await action()
      await router.invalidate()
      return true
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Request failed')
      return false
    } finally {
      setPending(false)
    }
  }

  return { error, setError, pending, run }
}

function OpdsServers() {
  const servers = Route.useLoaderData()
  const [adding, setAdding] = useState(false)
  const [deleting, setDeleting] = useState<Server | null>(null)

  return (
    <section className="grid gap-4">
      <div className="flex items-center justify-between">
        <h2 className="text-lg font-semibold">OPDS servers</h2>
        <Button onClick={() => setAdding(true)}>Add server</Button>
      </div>
      <div className="rounded-lg border">
        <Table>
          <TableHeader>
            <TableRow>
              <TableHead className="pl-4">Name</TableHead>
              <TableHead>URL</TableHead>
              <TableHead className="w-12" />
            </TableRow>
          </TableHeader>
          <TableBody>
            {servers.length === 0 && (
              <TableRow>
                <TableCell
                  colSpan={3}
                  className="py-8 text-center text-muted-foreground"
                >
                  No servers
                </TableCell>
              </TableRow>
            )}
            {servers.map((s) => (
              <TableRow key={s.id}>
                <TableCell className="pl-4 font-medium">{s.name}</TableCell>
                <TableCell className="max-w-0 truncate text-muted-foreground">
                  {s.url}
                </TableCell>
                <TableCell>
                  <Button
                    variant="ghost"
                    size="icon"
                    aria-label={`Remove ${s.name}`}
                    onClick={() => setDeleting(s)}
                  >
                    <Trash2 />
                  </Button>
                </TableCell>
              </TableRow>
            ))}
          </TableBody>
        </Table>
      </div>
      <AddServerDialog open={adding} onOpenChange={setAdding} />
      <RemoveServerDialog
        server={deleting}
        onClose={() => setDeleting(null)}
      />
    </section>
  )
}

function AddServerDialog({
  open,
  onOpenChange,
}: {
  open: boolean
  onOpenChange: (open: boolean) => void
}) {
  const { error, setError, pending, run } = useAction()

  async function onSubmit(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault()
    const form = new FormData(event.currentTarget)
    const ok = await run(() =>
      addOpdsServer({
        data: {
          name: String(form.get('name')),
          url: String(form.get('url')),
        },
      }),
    )
    if (ok) onOpenChange(false)
  }

  return (
    <Dialog
      open={open}
      onOpenChange={(next) => {
        setError('')
        onOpenChange(next)
      }}
    >
      <DialogContent className="sm:max-w-md">
        <DialogHeader>
          <DialogTitle>Add OPDS server</DialogTitle>
        </DialogHeader>
        <form onSubmit={onSubmit} className="grid gap-4">
          <div className="grid gap-2">
            <Label htmlFor="opds-url">Catalog URL</Label>
            <Input
              id="opds-url"
              name="url"
              type="url"
              placeholder="https://example.com/opds"
              required
            />
          </div>
          <div className="grid gap-2">
            <Label htmlFor="opds-name">Name</Label>
            <Input
              id="opds-name"
              name="name"
              placeholder="From the catalog"
              autoComplete="off"
            />
          </div>
          {error && <p className="text-sm text-destructive">{error}</p>}
          <DialogFooter>
            <Button type="submit" disabled={pending}>
              Add server
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  )
}

function RemoveServerDialog({
  server,
  onClose,
}: {
  server: Server | null
  onClose: () => void
}) {
  const { error, setError, pending, run } = useAction()

  async function onConfirm(event: React.MouseEvent) {
    event.preventDefault()
    if (!server) return
    const ok = await run(() => removeOpdsServer({ data: server.id }))
    if (ok) onClose()
  }

  return (
    <AlertDialog
      open={server !== null}
      onOpenChange={(open) => {
        if (open) return
        setError('')
        onClose()
      }}
    >
      <AlertDialogContent>
        <AlertDialogHeader>
          <AlertDialogTitle>Remove {server?.name}?</AlertDialogTitle>
        </AlertDialogHeader>
        {error && <p className="text-sm text-destructive">{error}</p>}
        <AlertDialogFooter>
          <AlertDialogCancel>Cancel</AlertDialogCancel>
          <AlertDialogAction
            variant="destructive"
            disabled={pending}
            onClick={onConfirm}
          >
            Remove
          </AlertDialogAction>
        </AlertDialogFooter>
      </AlertDialogContent>
    </AlertDialog>
  )
}

