import { useState } from 'react'
import {
  Link,
  createFileRoute,
  redirect,
  useNavigate,
  useRouterState,
} from '@tanstack/react-router'
import { Check, ChevronDown, ChevronRight, Plus, Store } from 'lucide-react'

import { BookCover } from '#/components/book-cover'
import { Button } from '#/components/ui/button'
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from '#/components/ui/dropdown-menu'
import { Input } from '#/components/ui/input'
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '#/components/ui/select'
import type { OpdsEntry } from '#/lib/opds'
import {
  addFromOpds,
  browseOpds,
  listOpdsServers,
} from '#/lib/opds-functions'
import { cn } from '#/lib/utils'

type MarketSearch = { server?: number; url?: string; q?: string }

// Browses the OPDS servers set up in Settings. `url` is the feed being viewed
// (the server's root when absent) and `q` searches from that feed.
export const Route = createFileRoute('/_app/market')({
  beforeLoad: ({ context }) => {
    if (context.user.role !== 'admin') throw redirect({ to: '/' })
  },
  validateSearch: (search: Record<string, unknown>): MarketSearch => ({
    server: Number(search.server) || undefined,
    url: typeof search.url === 'string' ? search.url : undefined,
    q: typeof search.q === 'string' ? search.q : undefined,
  }),
  loaderDeps: ({ search }) => search,
  loader: async ({ deps }) => {
    const servers = await listOpdsServers()
    const server = servers.find((s) => s.id === deps.server) ?? servers[0]
    if (!server) return { servers, server: null, result: null }
    const result = await browseOpds({
      data: { serverId: server.id, url: deps.url, q: deps.q },
    })
    return { servers, server, result }
  },
  component: Market,
})

function Market() {
  const { servers, server, result } = Route.useLoaderData()
  const search = Route.useSearch()
  const navigate = useNavigate({ from: Route.fullPath })
  const loading = useRouterState({ select: (s) => s.status === 'pending' })

  if (!server) {
    return (
      <main className="mx-auto max-w-6xl px-4 py-8">
        <h1 className="text-2xl font-semibold">Market</h1>
        <div className="mt-6 flex min-h-72 flex-col items-center justify-center gap-3 rounded-lg border border-dashed text-muted-foreground">
          <Store className="size-8" />
          <p className="text-sm">No OPDS servers</p>
          <Button asChild variant="outline" size="sm">
            <Link to="/settings/opds">Add a server</Link>
          </Button>
        </div>
      </main>
    )
  }

  const feed = result?.feed
  const books = feed?.entries.filter((e) => e.downloads.length) ?? []
  const others = feed?.entries.filter((e) => !e.downloads.length) ?? []
  const atRoot = !search.url && !search.q

  return (
    <main className="mx-auto max-w-6xl px-4 py-8">
      <div className="flex flex-wrap items-center gap-3">
        <h1 className="mr-auto text-2xl font-semibold">Market</h1>
        {feed?.searchable && (
          <form
            key={`${server.id} ${search.url} ${search.q}`}
            className="w-full sm:w-56"
            onSubmit={(e) => {
              e.preventDefault()
              const q = String(new FormData(e.currentTarget).get('q')).trim()
              void navigate({
                search: { server: server.id, url: search.url, q: q || undefined },
              })
            }}
          >
            <Input
              type="search"
              name="q"
              placeholder={`Search ${server.name}`}
              aria-label={`Search ${server.name}`}
              defaultValue={search.q}
            />
          </form>
        )}
        {servers.length > 1 && (
          <Select
            value={String(server.id)}
            onValueChange={(id) =>
              navigate({ search: { server: Number(id) } })
            }
          >
            <SelectTrigger aria-label="Server" className="w-full sm:w-48">
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              {servers.map((s) => (
                <SelectItem key={s.id} value={String(s.id)}>
                  {s.name}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        )}
      </div>

      <div
        className={cn(
          'mt-6 grid gap-6 transition-opacity',
          loading && 'opacity-60',
        )}
      >
        <nav className="flex min-w-0 items-center gap-1 text-sm text-muted-foreground">
          {atRoot ? (
            <span className="font-medium text-foreground">{server.name}</span>
          ) : (
            <>
              <Link
                to="/market"
                search={{ server: server.id }}
                className="shrink-0 hover:text-foreground"
              >
                {server.name}
              </Link>
              {feed && (
                <>
                  <ChevronRight className="size-4 shrink-0" />
                  <span className="truncate font-medium text-foreground">
                    {feed.title}
                  </span>
                </>
              )}
            </>
          )}
        </nav>

        {result?.error && (
          <p className="text-sm text-destructive">
            Could not load {server.name}: {result.error}
          </p>
        )}

        {feed && feed.entries.length === 0 && (
          <p className="text-sm text-muted-foreground">Nothing here</p>
        )}

        {others.length > 0 && (
          <ul className="divide-y rounded-lg border">
            {others.map((entry) => (
              <li key={entry.id}>
                <EntryRow entry={entry} serverId={server.id} />
              </li>
            ))}
          </ul>
        )}

        {books.length > 0 && (
          <ul className="grid grid-cols-2 gap-x-4 gap-y-6 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-6">
            {books.map((entry) => (
              <li key={entry.id}>
                <BookCard entry={entry} />
              </li>
            ))}
          </ul>
        )}

        {(feed?.previous || feed?.next) && (
          <div className="flex justify-between">
            {feed.previous ? (
              <Button asChild variant="outline">
                <Link
                  to="/market"
                  search={{ server: server.id, url: feed.previous }}
                >
                  Previous
                </Link>
              </Button>
            ) : (
              <span />
            )}
            {feed.next && (
              <Button asChild variant="outline">
                <Link
                  to="/market"
                  search={{ server: server.id, url: feed.next }}
                >
                  Next
                </Link>
              </Button>
            )}
          </div>
        )}
      </div>
    </main>
  )
}

// A link to another feed (category, author, search result...), or an entry
// with nothing to add (e.g. a book with no EPUB).
function EntryRow({ entry, serverId }: { entry: OpdsEntry; serverId: number }) {
  const body = (
    <div className="min-w-0 flex-1">
      <p className="truncate text-sm font-medium">{entry.title}</p>
      {(entry.authors.length > 0 || entry.summary) && (
        <p className="truncate text-sm text-muted-foreground">
          {entry.authors.join(', ') || entry.summary}
        </p>
      )}
    </div>
  )
  if (!entry.href) {
    return <div className="flex px-4 py-3 opacity-60">{body}</div>
  }
  return (
    <Link
      to="/market"
      search={{ server: serverId, url: entry.href }}
      className="flex items-center gap-3 px-4 py-3 transition-colors hover:bg-accent"
    >
      {body}
      <ChevronRight className="size-4 shrink-0 text-muted-foreground" />
    </Link>
  )
}

function BookCard({ entry }: { entry: OpdsEntry }) {
  const [state, setState] = useState<
    | { status: 'idle' | 'adding' }
    | { status: 'added'; bookId: string }
    | { status: 'error'; message: string }
  >({ status: 'idle' })

  async function add(href: string) {
    setState({ status: 'adding' })
    try {
      const { bookId } = await addFromOpds({
        data: { href, title: entry.title },
      })
      setState({ status: 'added', bookId })
    } catch (err) {
      setState({
        status: 'error',
        message: err instanceof Error ? err.message : 'Download failed',
      })
    }
  }

  const adding = state.status === 'adding'
  const label = adding ? 'Adding…' : 'Add to library'

  return (
    <div className="grid gap-2">
      <BookCover
        title={entry.title}
        authors={entry.authors}
        coverUrl={entry.coverUrl}
      />
      <div>
        <p className="line-clamp-2 text-sm font-medium">{entry.title}</p>
        <p className="line-clamp-1 text-xs text-muted-foreground">
          {entry.authors.join(', ')}
        </p>
      </div>
      {state.status === 'added' ? (
        <Button asChild variant="secondary" size="sm">
          <Link to="/books/$bookId" params={{ bookId: state.bookId }}>
            <Check />
            In library
          </Link>
        </Button>
      ) : entry.downloads.length === 1 ? (
        <Button
          size="sm"
          disabled={adding}
          onClick={() => add(entry.downloads[0].href)}
        >
          <Plus />
          {label}
        </Button>
      ) : (
        <DropdownMenu modal={false}>
          <DropdownMenuTrigger asChild>
            <Button size="sm" disabled={adding}>
              <Plus />
              {label}
              <ChevronDown />
            </Button>
          </DropdownMenuTrigger>
          <DropdownMenuContent align="start">
            {entry.downloads.map((d) => (
              <DropdownMenuItem key={d.href} onSelect={() => add(d.href)}>
                {d.title}
              </DropdownMenuItem>
            ))}
          </DropdownMenuContent>
        </DropdownMenu>
      )}
      {state.status === 'error' && (
        <p className="text-xs text-destructive">{state.message}</p>
      )}
    </div>
  )
}

